PRAGMA foreign_keys=ON;
CREATE TABLE dim_state (state_code TEXT PRIMARY KEY, state_name TEXT NOT NULL UNIQUE);
CREATE TABLE dim_date (month TEXT PRIMARY KEY, year INTEGER NOT NULL, month_number INTEGER NOT NULL CHECK(month_number BETWEEN 1 AND 12));
CREATE TABLE dim_quality_measure (measure_id TEXT PRIMARY KEY, measure_name TEXT NOT NULL, age_group TEXT NOT NULL, rate_unit TEXT NOT NULL, direction TEXT NOT NULL);
CREATE TABLE fact_enrollment (state_code TEXT NOT NULL REFERENCES dim_state, month TEXT NOT NULL REFERENCES dim_date, medicaid INTEGER CHECK(medicaid>=0), chip INTEGER CHECK(chip>=0), total INTEGER CHECK(total>=0), adult INTEGER CHECK(adult>=0), version TEXT NOT NULL, final_report TEXT NOT NULL, footnotes TEXT, source_file TEXT NOT NULL, source_row INTEGER NOT NULL, PRIMARY KEY(state_code,month));
CREATE TABLE fact_quality (record_id TEXT PRIMARY KEY, state_code TEXT REFERENCES dim_state, state_raw TEXT NOT NULL, report_year INTEGER NOT NULL, reference_year INTEGER NOT NULL, measure_id TEXT NOT NULL REFERENCES dim_quality_measure, rate_definition TEXT NOT NULL, population_raw TEXT, methodology_raw TEXT, rate_raw TEXT, rate REAL CHECK(rate BETWEEN 0 AND 100), rate_status TEXT, denominator_raw TEXT, denominator REAL, denominator_status TEXT, denominator_kind TEXT, official_selected INTEGER NOT NULL, target_rate INTEGER NOT NULL, map_eligible INTEGER NOT NULL, exclusion_reason TEXT, notes TEXT, comments TEXT, source_file TEXT NOT NULL, source_row INTEGER NOT NULL, official_median REAL, official_reporting_count REAL, timing_basis TEXT NOT NULL);
CREATE TABLE quality_review (state_code TEXT NOT NULL REFERENCES dim_state, measure_id TEXT NOT NULL REFERENCES dim_quality_measure, trend_tier TEXT NOT NULL CHECK(trend_tier IN ('primary','caution','exclude')), review_reason TEXT NOT NULL, PRIMARY KEY(state_code,measure_id));
CREATE INDEX quality_state_measure_year ON fact_quality(state_code,measure_id,report_year);
